const cliente = $('1. Receber cliente (Webhook)').first().json.body;
const csv = $input.first().json.data;

// CSV -> lista de objetos
const linhas = csv.trim().split(/\r?\n/);
const cab = linhas.shift().split(',').map(c => c.trim());
const produtos = linhas.map(l => {
  const v = l.split(',').map(c => c.trim());
  return Object.fromEntries(cab.map((c, i) => [c, v[i]]));
});

// "R$ 10.000" -> 10000
const saldo = Number(String(cliente.saldo).replace(/[^\d,]/g, '').replace(',', '.'));

// Cruza perfil + saldo mínimo
const opcoes = produtos.filter(p =>
  p.perfil.toLowerCase() === cliente.perfil.toLowerCase() &&
  (Number(p.minimo) || 0) <= saldo
);

const textos = {
  conservador: 'Foco em renda fixa e segurança.',
  moderado: 'Mix equilibrado entre renda fixa e variável.',
  arrojado: 'Ênfase em ações e maior potencial de retorno.'
};
const intro = textos[cliente.perfil.toLowerCase()] || 'Perfil não reconhecido.';
const lista = opcoes.map(o => `${o.produto} (${o.rentabilidade})`).join(', ') || 'nenhuma opção elegível';

return [{
  json: {
    nome_cliente: cliente.nome,
    email: cliente.email,
    perfil_investidor: cliente.perfil,
    saldo_atual: cliente.saldo,
    opcoes_elegiveis: opcoes,
    mensagem_sugerida: `Olá, ${cliente.nome}! Seu perfil é ${cliente.perfil} e seu saldo é ${cliente.saldo}. ${intro} Opções para você: ${lista}.`
  }
}];
